// The decoded TableData is structurally exact, not just emit-equal.
fn test_ast_bin_table_payload_structural() {
	doc := cx.parse('[users [table[name::string age::int note]]
  alice 30 null
  bob 25 admin
]') or { panic(err) }
	bytes := cx.emit_ast_bin(doc)
	doc2 := cx.bin_to_doc(bytes) or { panic('bin_to_doc: ${err}') }
	root := doc2.root() or { panic('no root') }
	assert root.name == 'users'
	dt := root.data_type() or { panic('data_type lost') }
	assert dt == 'table'
	td := root.table_opt() or { panic('table payload lost through ast_bin (#464)') }
	assert td.cols.len == 3
	assert td.cols[0].name == 'name'
	assert td.cols[0].type_name == 'string'
	assert td.cols[1].name == 'age'
	assert td.cols[1].type_name == 'int'
	assert td.cols[2].name == 'note'
	assert td.cols[2].type_name == ''
	assert td.rows.len == 2
	c00 := td.rows[0][0]
	assert c00 is string
	if c00 is string { assert c00 == 'alice' }
	c01 := td.rows[0][1]
	assert c01 is i64
	if c01 is i64 { assert c01 == 30 }
	assert td.rows[0][2] is cx.NullValue
	// from_chunked is runtime provenance, NOT on the wire — restores false.
	assert !td.from_chunked
}

// A table element that ALSO carries attrs and body items (constructible
// via the AST API even though the text parser produces table-only
// bodies): the wire carries all three channels.
fn test_ast_bin_table_with_attrs_and_children() {
	base := cx.parse('[cfg region=west [child 1]]') or { panic(err) }
	root := base.root() or { panic('no root') }
	td := &cx.TableData{
		cols: [cx.TableColumn{
			name: 'k'
		}, cx.TableColumn{
			name:      'v'
			type_name: 'int'
		}]
		rows: [[cx.TableCellValue('a'), cx.TableCellValue(i64(1))],
			[cx.TableCellValue('b'), cx.TableCellValue(i64(2))]]
	}
	el := root.with_table(td)
	doc := cx.Document{
		elements: [cx.Node(el)]
	}
	bytes := cx.emit_ast_bin(doc)
	doc2 := cx.bin_to_doc(bytes) or { panic('bin_to_doc: ${err}') }
	root2 := doc2.root() or { panic('no root') }
	assert root2.attr('region') == 'west'
	assert root2.items.len == 1
	td2 := root2.table_opt() or { panic('table lost') }
	assert td2.cols.len == 2
	assert td2.rows.len == 2
	c := td2.rows[1][1]
	assert c is i64
	if c is i64 { assert c == 2 }
}

// Single-node frames (cxstore content-addressed engine) carry the
// payload too.
fn test_node_bin_table_round_trip() {
	doc := cx.parse('[t [table[a b::int]]
  x 1
]') or { panic(err) }
	root := doc.root() or { panic('no root') }
	bytes := cx.emit_node_bin(cx.Node(root))
	n2 := cx.node_from_bin(bytes) or { panic('node_from_bin: ${err}') }
	el2 := n2 as cx.Element
	td := el2.table_opt() or { panic('table lost through node frame') }
	assert td.rows.len == 1
}

// ── version discipline ────────────────────────────────────────────────────────

// Table-bearing documents bump the envelope to v9; table-free documents
// keep their previous version byte (6 common case) so existing readers
// keep decoding every buffer they could decode before (additive rule).
fn test_ast_bin_version_bumps_only_for_tables() {
	plain := cx.parse('[a [b]]') or { panic(err) }
	plain_bytes := cx.emit_ast_bin(plain)
	assert plain_bytes[4] == 6, 'table-free doc must stay at v6, got ${plain_bytes[4]}'

	tdoc := cx.parse('[t [table[a]]
  x
]') or { panic(err) }
	tbytes := cx.emit_ast_bin(tdoc)
	assert tbytes[4] == 9, 'table-bearing doc must emit v9, got ${tbytes[4]}'
}

// ── malformed payload rejection (fail-loud, #464 acceptance) ──────────────────

// build_table_doc_bytes returns the framed v9 bytes of
// `[t [table[a b]] x y]` for byte-surgery tests.
fn build_table_doc_bytes() []u8 {
	doc := cx.parse('[t [table[a b]]
  x y
]') or { panic(err) }
	return cx.emit_ast_bin(doc)
}

fn test_ast_bin_rejects_table_tag_below_v9() {
	mut bytes := build_table_doc_bytes()
	// Rewind the version byte to 8: tag 0x17 must not decode in a <v9
	// envelope (producers never emitted it before v9).
	bytes[4] = 8
	if _ := cx.bin_to_doc(bytes) {
		assert false, 'tag 0x17 in a v8 envelope must be rejected'
	} else {
		assert err.msg().contains('0x17') || err.msg().contains('table'), 'reject must name the table tag: ${err.msg()}'
	}
}

fn test_ast_bin_rejects_table_at_top_level() {
	// Splice the table record (starts at the element's first child slot)
	// into top-level element position: version 9, 0 prolog, 1 element
	// that IS the 0x17 record. The decoder must reject 0x17 outside an
	// Element child list.
	src := build_table_doc_bytes()
	// find the 0x17 tag: it is the first child of the root element.
	mut off := -1
	for i in 4 .. src.len {
		if src[i] == 0x17 {
			off = i
			break
		}
	}
	assert off > 0, 'fixture bytes must contain a 0x17 record'
	record := src[off..]
	mut payload := []u8{}
	payload << u8(9) // version
	payload << [u8(0), 0] // prolog_count
	payload << [u8(1), 0] // element_count
	payload << record
	mut framed := []u8{}
	sz := u32(payload.len)
	framed << u8(sz & 0xFF)
	framed << u8((sz >> 8) & 0xFF)
	framed << u8((sz >> 16) & 0xFF)
	framed << u8(sz >> 24)
	framed << payload
	if _ := cx.bin_to_doc(framed) {
		assert false, 'top-level 0x17 table record must be rejected'
	} else {
		assert err.msg().contains('table'), 'reject must be loud about table position: ${err.msg()}'
	}
}

fn test_ast_bin_rejects_row_cell_count_mismatch() {
	mut bytes := build_table_doc_bytes()
	// The row record is `u16:cell_count cells[]` with cell_count == 2
	// (cols a b). Find the 0x17 record, then corrupt the row's
	// cell_count. Layout after 0x17: u16 col_count=2, col a (Str name
	// 'a' + Str type ''), col b, u32 row_count=1, u16 cell_count=2.
	mut off := -1
	for i in 4 .. bytes.len {
		if bytes[i] == 0x17 {
			off = i
			break
		}
	}
	assert off > 0
	// walk: tag(1) colcount(2) + col'a'(4+1 + 4+0) + col'b'(4+1 + 4+0) + rowcount(4)
	cc_off := off + 1 + 2 + 9 + 9 + 4
	assert bytes[cc_off] == 2 && bytes[cc_off + 1] == 0, 'cell_count not at expected offset'
	bytes[cc_off] = 3
	if _ := cx.bin_to_doc(bytes) {
		assert false, 'row cell_count != col_count must be rejected'
	} else {
		assert err.msg().contains('cell'), 'reject must name the cell-count mismatch: ${err.msg()}'
	}
}

fn test_ast_bin_rejects_non_cell_node_kind() {
	mut bytes := build_table_doc_bytes()
	// First cell is Scalar (0x03) 'string' 'x'. Rewrite its tag to 0x04
	// (Comment) — same payload shape (one String), so the decode
	// succeeds structurally and MUST fail on the cell-kind check.
	mut off := -1
	for i in 4 .. bytes.len {
		if bytes[i] == 0x17 {
			off = i
			break
		}
	}
	assert off > 0
	cell_off := off + 1 + 2 + 9 + 9 + 4 + 2
	assert bytes[cell_off] == 0x03, 'first cell tag not at expected offset'
	bytes[cell_off] = 0x04
	if _ := cx.bin_to_doc(bytes) {
		assert false, 'non-Scalar/collection cell node must be rejected'
	} else {
		assert err.msg().contains('cell'), 'reject must name the bad cell kind: ${err.msg()}'
	}
}

// ── source: vcx/tests/ast_json_table_test.v ──
// #443 — the AST-JSON projection carries the pooled TableData payload
// ("table": {"cols": …, "rows": …}) and parser_ast_json reconstructs it,
// so CX → emit_ast_json → parse_ast_json → emit_cx is the identity on
// table-bearing documents. Before the fix the projection emitted a
// rowless `"items":[]` and the round-trip silently produced a bare
// `[name::table]`.

// round-trips SRC through the AST-JSON wire and asserts the recovered
// canonical CX equals the direct canonical CX of the source.
fn assert_ast_json_roundtrip(src string) {
	want := cx.to_cx(src) or { panic('to_cx: ${err}') }
	wire := cx.to_ast(src) or { panic('to_ast: ${err}') }
	got := cx.ast_to_cx(wire) or { panic('ast_to_cx: ${err}') }
	assert got == want, 'AST-JSON round-trip drifted\n  src:  ${src}\n  wire: ${wire}\n  want: ${want}\n  got:  ${got}'
}

fn test_ast_json_table_scalar_cells_roundtrip() {
	assert_ast_json_roundtrip('[users [table[name::string age::int active::bool score::float]]
  alice 30 true 1.5
  bob 25 false 2.0
]')
}

fn test_ast_json_table_null_empty_and_quoted_cells_roundtrip() {
	// '' (empty string), null, a string that looks numeric under a string
	// column, and a quoted string in an int-typed column context.
	assert_ast_json_roundtrip("[t [table[a b]]
  '' null
  '12' x
]")
}

fn test_ast_json_table_collection_cells_roundtrip() {
	assert_ast_json_roundtrip('[t [table[name value]]
  tags [admin, user]
  meta {role: admin, age: 30}
  ports (80, 443)
]')
}

fn test_ast_json_table_header_only_roundtrip() {
	assert_ast_json_roundtrip('[t [table[a::int b]]
]')
}

fn test_ast_json_table_wire_shape() {
	wire := cx.to_ast('[users [table[name::string age::int]]
  alice 30
]') or { panic(err) }
	// cols carry name + dataType; rows are arrays of JSON-native cells;
	// the redundant empty "items" is suppressed when "table" is present.
	assert wire.contains('"table":{"cols":[{"name":"name","dataType":"string"},{"name":"age","dataType":"int"}],"rows":[["alice",30]]}')
	assert !wire.contains('"items"')
}

fn test_ast_json_untyped_column_omits_datatype() {
	wire := cx.to_ast('[t [table[a::int b]]
]') or { panic(err) }
	assert wire.contains('{"name":"a","dataType":"int"},{"name":"b"}')
}

// The collection-node importer arms added for table cells also unlock
// collection literals in ordinary body position (emit_ast_json has
// always produced them; the importer used to reject the wire with
// "unknown AST node type: Array").
fn test_ast_json_body_collection_literals_roundtrip() {
	assert_ast_json_roundtrip("[t [tags ['admin', 'user']] [ports (80, 443)] [meta {role: admin}]]")
}

// ── source: vcx/tests/data_bin_test.v ──
// Round-trip tests for CXCol v1: cx -> emit_data_bin -> parse_data_bin
// -> emit_cx -> equivalent shape. Spec: spec/core/data-bin.md.
// ── Header ───────────────────────────────────────────────────────────────────

fn test_data_bin_emits_magic_and_version() {
	doc := cx.parse('[a]') or { panic(err) }
	bytes := cx.emit_data_bin(doc) or { panic('emit: ${err}') }
	// Frame: [u32 LE size][CXCol ...].
	assert bytes.len >= 16, 'expected at least header + framing; got ${bytes.len}'
	// Bytes 4..9 = 5-byte magic "CXCol" (spec/core/data-bin.md §3.1).
	assert bytes[4] == 0x43 && bytes[5] == 0x58 && bytes[6] == 0x43
		&& bytes[7] == 0x6F && bytes[8] == 0x6C
	// Byte 9 = version 0x01
	assert bytes[9] == 0x01
}

// ── #918: the 0x52 extended-map form (typed keys + declarations) ────────────

fn test_data_bin_ext_map_round_trips_typed_keys_and_declarations() {
	// A map carrying an ascribed key or a declaration-only entry rides
	// version 2 with the 0x52 form and restores EXACTLY; the value slot of
	// a declaration is ABSENT (never null) on the way back.
	src := '{1.10::decimal: 3, a: ::string, b: 2}'
	doc := cx.parse(src) or { panic(err) }
	bytes := cx.emit_data_bin(doc) or { panic('emit: ${err}') }
	assert bytes[9] == 0x02, 'expected version 2 for an ext-map document; got ${bytes[9]}'
	doc2 := cx.parse_data_bin(bytes) or { panic('decode failed: ${err}') }
	orig := cx.cx_text_canonical(src) or { panic(err) }
	got := cx.cx_text_canonical(cx.emit_cx(doc2)) or { panic(err) }
	assert got == orig, 'ext-map round trip moved: ${got} != ${orig}'
}

fn test_data_bin_plain_maps_stay_version_one() {
	// The additive discipline: a document with no typed key and no
	// declaration keeps the byte-identical v1 envelope.
	doc := cx.parse('[env {host: 5, port: 8080}]') or { panic(err) }
	bytes := cx.emit_data_bin(doc) or { panic('emit: ${err}') }
	assert bytes[9] == 0x01, 'plain map must stay version 1; got ${bytes[9]}'
}

// ── #919: collection carriers decode at the DOCUMENT ROOT ────────────────────

fn test_xml_root_collection_carriers_round_trip() {
	// A top-level bare map/array/sequence document emits a root
	// <cx:map>/<cx:arr>/<cx:seq> — the import must invert it at the root
	// exactly as it always did in child position (#919; declarations and
	// typed keys included).
	for src in ['{a: 5, b: 6}', '[1, 2, 3]', '(1, 2, 3)', '{a: ::int, b: 5}',
		'{1.10::decimal: x}'] {
		xml := cx.convert_by_name(src, 'cx', 'xml', false) or { panic('emit ${src}: ${err}') }
		back := cx.convert_by_name(xml, 'xml', 'cx', false) or { panic('import ${src}: ${err}') }
		orig := cx.cx_text_canonical(src) or { panic(err) }
		got := cx.cx_text_canonical(back) or { panic(err) }
		assert got == orig, 'xml root carrier moved for ${src}: ${got} != ${orig}'
	}
}

