// ── Decoder rejects invalid input ────────────────────────────────────────────

fn test_data_bin_rejects_bad_magic() {
	mut bytes := []u8{len: 16}
	// Frame size = 12, valid prefix.
	bytes[0] = 12
	bytes[1] = 0
	bytes[2] = 0
	bytes[3] = 0
	// Invalid magic.
	bytes[4] = 0x42
	bytes[5] = 0x42
	bytes[6] = 0x42
	bytes[7] = 0x42
	if _ := cx.parse_data_bin(bytes) {
		assert false, 'decoder should reject bad magic'
	} else {
		assert err.msg().contains('magic'), 'expected magic-related error, got: ${err.msg()}'
	}
}

fn test_data_bin_rejects_truncated_size_header() {
	bytes := [u8(0x01), 0x00]  // only 2 bytes, less than the 4-byte size prefix
	if _ := cx.parse_data_bin(bytes) {
		assert false, 'decoder should reject truncated input'
	} else {
		assert err.msg().contains('short')
	}
}

// ── Idempotent canonical form ────────────────────────────────────────────────

fn test_data_bin_idempotent() {
	doc := cx.parse('[server host=localhost port=8080]') or { panic(err) }
	a := cx.emit_data_bin(doc) or { panic('emit: ${err}') }
	b := cx.emit_data_bin(doc) or { panic('emit: ${err}') }
	assert a == b, 'emit_data_bin must be deterministic for the same input'
}

fn test_data_bin_preserves_decimal_kind_on_wire() {
	// I1 row 16 (L46): the 0x28 tag — the KIND survives, not just the image.
	doc := cx.parse('[price 19.99]') or { panic(err) }
	bytes := cx.emit_data_bin(doc) or { panic('emit: ${err}') }
	doc2 := cx.parse_data_bin(bytes) or { panic(err) }
	assert cx.cx_text_hash(cx.emit_cx(doc2)) or { panic(err) } == cx.cx_text_hash('[price 19.99]') or {
		panic(err)
	}, 'decimal kind lost through the wire'
}

fn test_data_bin_preserves_bigint_kind_within_i64() {
	// Narrowing-within-kind: an in-i64 bigint stays 0x18 (never 0x13).
	doc := cx.parse('[n::bigint 42]') or { panic(err) }
	bytes := cx.emit_data_bin(doc) or { panic('emit: ${err}') }
	doc2 := cx.parse_data_bin(bytes) or { panic(err) }
	out := cx.emit_cx(doc2)
	assert out.contains('::bigint') || out.contains('42'), out
	h1 := cx.cx_data_bin_hash(bytes) or { panic(err) }
	h2 := cx.cx_text_hash('[n::bigint 42]') or { panic(err) }
	assert h1 == h2, 'bigint kind narrowed away on the wire'
}

// ── source: vcx/tests/data_bin_one_shots_test.v ──
// imported for its `init()` side effect: registers the strict, lossless json
// codec parser into the cx registry (item C). cx.parse_to_doc('json', …) below
// resolves to it; without this import the json codec has no parser.
// Round-trip tests for the data_bin one-shot loaders/dumpers per
// spec/abi.md §2.4–§2.5. Each test exercises the same composition the
// new C ABI symbols (cx_<fmt>_to_data_bin / cx_data_bin_to_<fmt>)
// wrap, hitting the per-format parser, emit_data_bin, parse_data_bin,
// and the per-format emitter in one round-trip.
// ── XML one-shot ─────────────────────────────────────────────────────────────

fn test_xml_round_trip_through_data_bin() {
	src := '<server><host>localhost</host><port>8080</port></server>'
	// xml → data_bin
	doc := cx.parse_xml(src) or { panic('parse_xml: ${err}') }
	bytes := cx.emit_data_bin(doc) or { panic('emit: ${err}') }
	assert bytes.len > 8, 'expected non-empty data_bin payload'
	// data_bin → xml (round-trip)
	doc2 := cx.parse_data_bin(bytes) or { panic('parse_data_bin: ${err}') }
	out := cx.emit_xml(doc2)
	// CX's XML round-trip may choose attribute or child-element shape
	// for scalar-bodied children; both are valid representations of
	// the same semantic content. Assert on data preservation, not
	// specific shape.
	assert out.contains('server'), 'expected server in xml output, got: ${out}'
	assert out.contains('localhost'), 'expected localhost in xml output, got: ${out}'
	assert out.contains('8080'), 'expected 8080 in xml output, got: ${out}'
}

