fn test_emit_doublequote_doubling() {
	src := "[t [table[name::string note::string]]
  alice 'she said \"hi\"'
]"
	out := cx.to_csv(src) or { panic(err) }
	// Embedded `\"` is doubled; the whole field is quoted because it
