fn test_parse_csv_basic() {
	csv_in := 'name,age,active\nalice,30,true\nbob,25,false\n'
	out := cx.from_csv(csv_in) or { panic(err) }
	// Auto-typing should narrow age → :int and active → :bool.
	expected := '[table [table[name age::int active::bool]]
  alice 30 true
  bob 25 false
]'
	assert out == expected
}

fn test_parse_csv_quoted_string_stays_string() {
	// Quoted "30" should NOT auto-type to int — quoting is the
	// explicit "this is a string" signal.
	csv_in := 'name,age\nalice,"30"\nbob,"25"\n'
	out := cx.from_csv(csv_in) or { panic(err) }
	expected := '[table [table[name age]]
  alice 30
  bob 25
]'
	assert out == expected
}

fn test_parse_csv_singlequote() {
	csv_in := "name,note\nalice,'hello, world'\n"
	out := cx.from_csv(csv_in) or { panic(err) }
	// Single-quoted field with embedded delimiter; emitted as a
	// quoted CX string because it contains comma + space.
	expected := "[table [table[name note]]
  alice 'hello, world'
]"
	assert out == expected
}

fn test_parse_csv_doublequote_doubling() {
	csv_in := 'name,note\nalice,"she said ""hi"""\n'
	out := cx.from_csv(csv_in) or { panic(err) }
	expected := "[table [table[name note]]
  alice 'she said \"hi\"'
]"
	assert out == expected
}

fn test_parse_csv_empty_cell_is_null() {
	csv_in := 'name,age\nalice,30\nbob,\n'
	out := cx.from_csv(csv_in) or { panic(err) }
	// age narrows to :int (null doesn't constrain the column type).
	expected := '[table [table[name age::int]]
  alice 30
  bob null
]'
	assert out == expected
}

fn test_parse_csv_crlf() {
	csv_in := 'a,b\r\n1,2\r\n3,4\r\n'
	out := cx.from_csv(csv_in) or { panic(err) }
	expected := '[table [table[a::int b::int]]
  1 2
  3 4
]'
	assert out == expected
}

fn test_roundtrip_table() {
	src := '[users [table[name::string age::int active::bool]]
  alice 30 true
  bob 25 false
]'
	csv_out := cx.to_csv(src) or { panic(err) }
	cx_back := cx.from_csv(csv_out) or { panic(err) }
	// Element name defaults to `table` on parse — original `users`
	// is not recoverable from CSV. Type narrowing
	// recovers the int/bool types.
	expected := '[table [table[name age::int active::bool]]
  alice 30 true
  bob 25 false
]'
	assert cx_back == expected
}

fn test_invalid_delimiter_errors() {
	if _ := cx.to_delimited('[t [table[a]]\n  x\n]', `"`) {
		assert false, 'expected error for double-quote delimiter'
	} else {
		assert true
	}
}

fn test_emit_psv() {
	src := '[t [table[a b]]
  x y
]'
	out := cx.to_psv(src) or { panic(err) }
	expected := 'a|b\r\nx|y\r\n'
	assert out == expected
}

// ── source: vcx/tests/fmt_lossless_test.v ──
// v0.8.0 — `cx fmt` lossless + idempotent contract (canonical.md §2.1).
//
// `cx_text_fmt` is the LOSSLESS canonical formatter: unlike `cx_text_canonical`
// (which strips presentation) it MUST round-trip comments, and its output MUST
// be a fixpoint — `fmt(fmt(x)) == fmt(x)` — so format-on-save never mutates a
// buffer twice for the same content. Two regressions are pinned here:
//
//   1. COMMENT LOSS — `[a 1] # keep me` used to drop the comment (emit was
//      byte-identical to `cx canonical`). Comments now round-trip wherever the
//      canonical layout has a line of their own: the document top level
//      (prolog / between+after root nodes) and the line-broken body of a
//      multi-child element. (Inline-only positions — an element head/attrs, an
//      inline `[a, b]` comma list — have no canonical home for a comment and
//      are out of scope by construction; the formatter stays idempotent there.)
//
//   2. NON-IDEMPOTENT ARRAYS — `[origins https://a.com, https://b.com]` emitted
//      a QUOTED array `['https://a.com', …]` on the first pass and a BARE one
//      `[https://a.com, …]` on the second (oscillation). A comma-body string
//      item (a string ScalarNode) and the same item re-parsed from `[ … ]`
//      literal form (a TextNode) now canonicalise identically per §2.3
//      bare-eligibility, so the first pass already lands on the fixpoint.

fn fmt(src string) string {
	return cx.cx_text_fmt(src) or { panic('cx_text_fmt: ${err}') }
}

fn assert_idempotent(src string) string {
	once := fmt(src)
	twice := fmt(once)
	assert once == twice, 'fmt not idempotent:\n  once=  |${once}|\n  twice= |${twice}|'
	return once
}

// ── Acceptance (a): fmt preserves a trailing `# comment` ─────────────────────

fn test_fmt_preserves_trailing_comment() {
	out := assert_idempotent('[a 1]  # keep me')
	assert out.contains('# keep me'), 'trailing comment dropped: |${out}|'
	// The element itself survives intact.
	assert out.contains('[a 1]')
}

fn test_fmt_preserves_leading_comment() {
	out := assert_idempotent('# config header\n[a 1]')
	assert out.contains('# config header'), 'leading comment dropped: |${out}|'
}

fn test_fmt_preserves_comment_between_root_elements() {
	out := assert_idempotent('[a]\n# between a and b\n[b]')
	assert out.contains('# between a and b'), 'between-element comment dropped: |${out}|'
	// Document order is preserved: comment sits between the two elements.
	ia := out.index('[a]') or { -1 }
	ic := out.index('# between') or { -1 }
	ib := out.index('[b]') or { -1 }
	assert ia >= 0 && ic > ia && ib > ic, 'comment out of order: |${out}|'
}

fn test_fmt_preserves_comment_between_child_elements() {
	out := assert_idempotent('[a\n  [b 1]\n  # mid\n  [c 2]\n]')
	assert out.contains('# mid'), 'child-body comment dropped: |${out}|'
}

fn test_fmt_preserves_trailing_comment_in_child_body() {
	out := assert_idempotent('[a\n  [b 1]\n  [c 2]\n  # tail\n]')
	assert out.contains('# tail'), 'trailing child-body comment dropped: |${out}|'
}

// ── Acceptance (b): fmt(fmt(x)) == fmt(x) for array / nested forms ───────────

fn test_idempotent_bareword_comma_array_safe_tokens() {
	// Bare-eligible string items (URLs: no ws/brackets/quotes, no auto-type)
	// canonicalise BARE per §2.3 and stay put on re-format.
	out := assert_idempotent('[origins https://a.com, https://b.com]')
	assert out == '[origins [https://a.com, https://b.com]]', 'unexpected: |${out}|'
}

fn test_idempotent_bareword_comma_array_names() {
	// Bare NAMES must quote (a bare `[admin]` re-parses as an element head, 3a),
	// and the quoted form is itself a fixpoint.
	out := assert_idempotent('[tags admin, user]')
	assert out == "[tags ['admin', 'user']]", 'unexpected: |${out}|'
}

fn test_idempotent_quoted_array_literal() {
	// A quoted array literal of bare-eligible strings normalises to the bare
	// canonical form in ONE pass (no quoted⇄bare oscillation).
	out := assert_idempotent("[urls ['https://a.com', 'https://b.com']]")
	assert out == '[urls [https://a.com, https://b.com]]', 'unexpected: |${out}|'
}

fn test_idempotent_quoted_array_literal_needing_quotes() {
	// Items that would split / re-type stay quoted, and the quoting is stable.
	out := assert_idempotent("[xs ['a b', '80', 'x,y']]")
	assert out.contains("'a b'") && out.contains("'80'") && out.contains("'x,y'"), 'unexpected: |${out}|'
}

fn test_idempotent_typed_int_array() {
	out := assert_idempotent('[ports 80, 443]')
	assert out == '[ports [80, 443]]', 'unexpected: |${out}|'
}

fn test_idempotent_typed_scalar_list_no_comma() {
	// No-comma discrete typed list (ast.md): each token is its own typed child.
	out := assert_idempotent('[scores 10 20 30]')
}

fn test_idempotent_nested_elements() {
	out := assert_idempotent('[a\n  [b 1]\n  [c\n    [d 2]\n    [e 3]\n  ]\n]')
	assert out.contains('[d 2]') && out.contains('[e 3]')
}

// ── Acceptance (b'): EXPLICITLY-typed arrays `::T[]` are lossless + idempotent.
// A typed array keeps its `::T[]` head and whitespace-separated items — the old
// "drop annotation + comma/whitespace signal" form was neither lossless (the
// `::T[]` was discarded) nor a fixpoint (`[scores 80 443]` re-parses to discrete
// children, `[tags admin, user]` to an untyped array). ─────────────────────────

fn test_idempotent_typed_string_array_keeps_annotation() {
	out := assert_idempotent('[tags::string[] admin user guest]')
	assert out == '[tags::string[] admin user guest]', 'unexpected: |${out}|'
}

fn test_idempotent_typed_int_array_keeps_annotation() {
	out := assert_idempotent('[scores::int[] 10 20 30]')
	assert out == '[scores::int[] 10 20 30]', 'unexpected: |${out}|'
}

fn test_idempotent_typed_float_array_no_type_loss() {
	// Integer-looking floats MUST keep `::float[]` — dropping it would re-infer
	// `int` on the next parse (silent type loss).
	out := assert_idempotent('[xs::float[] 1 2 3]')
	assert out.contains('::float[]'), 'float type lost: |${out}|'
}

fn test_idempotent_typed_empty_and_single() {
	assert assert_idempotent('[tags::string[]]') == '[tags::string[]]'
	assert assert_idempotent('[tags::string[] solo]') == '[tags::string[] solo]'
}

// ── Acceptance (c): mixed-content prose round-trips losslessly + idempotently.
// A bijective body-string quote rule (boundary whitespace, leading sigil like
// `+tls`, embedded comma) plus a bare-apostrophe contraction (`it's`) that the
// lookahead scanner used to mis-read as a string opener. ─────────────────────

fn test_idempotent_mixed_content_text_runs() {
	out := assert_idempotent("[p 'See the ' [a x] ' for it, now']")
	assert out.contains("'See the '") && out.contains("' for it, now'"), 'unexpected: |${out}|'
}

fn test_idempotent_sigil_leading_string_quoted() {
	// `'+tls'` must stay quoted — bare `+tls` re-parses as a retired flag sigil.
	out := assert_idempotent("[code '+tls']")
	assert out == "[code '+tls']", 'unexpected: |${out}|'
}

fn test_idempotent_bare_apostrophe_then_comma_quote() {
	// Regression: `it's` (bare contraction) followed by a sibling whose quoted
	// run contains a comma used to throw "unterminated quoted text" at EOF
	// (skip_bracket_region read the apostrophe as a string opener).
	out := assert_idempotent("[doc\n  [h2 What's Next]\n  [p 'See the ' [a x] ' for a, b, c.']\n]")
	assert out.contains("What's Next"), 'unexpected: |${out}|'
}

fn test_idempotent_attrs_and_children() {
	out := assert_idempotent('[server host=localhost port=8080\n  [route /a]\n  [route /b]\n]')
	assert out.contains('host=localhost') && out.contains('port=8080')
}

// ── Strict canonical still STRIPS comments (fmt ≠ canonical here) ────────────

fn test_canonical_still_strips_comments() {
	canon := cx.cx_text_canonical('[a 1]  # keep me') or { panic('canonical: ${err}') }
	assert !canon.contains('# keep me'), 'canonical must strip comments: |${canon}|'
	assert canon.contains('[a 1]')
}

// ── #400: fmt must not corrupt [?match] programs ─────────────────────────────
// The program emitter used to render match clause children in the RETIRED
// `:label` colon-slot spelling — a TEXT fixed point whose reparse held bare
// atoms where the source held clauses, so `cx fmt` rewrote a valid runnable
// match into text that failed evaluation. Two guards now hold:
//   (1) emit_match_directive is parse_match_clause's exact inverse (clause
//       surface out), and
//   (2) fmt's meaning checks compare position-insensitive AST SHAPES, not
//       just canonical text, so any future non-injective emitter output
//       fails closed to the original text.

fn test_fmt_match_keeps_clause_surface() {
	src := '[?match :a [case :a :ok]]'
	out := code.fmt_source(src) or { panic('fmt: ${err}') }
	assert out.contains('[case :a :ok]'), 'clause surface lost: |${out}|'
	assert !out.contains(':case'), 'retired colon-slot spelling leaked: |${out}|'
}

fn test_fmt_match_full_clause_vocabulary_round_trips() {
	src := '[?match $x [case [user @age=$a] [where [>= $a 18]] "adult"] [when [= $x 1] "one"] [else "other"]]'
	out := code.fmt_source(src) or { panic('fmt: ${err}') }
	assert out == src, 'canonical match surface must be a fixed point: |${out}|'
}

fn test_fmt_match_output_still_evaluates() {
	src := '[?match :a [case :a "hit"] [else "miss"]]'
	out := code.fmt_source(src) or { panic('fmt: ${err}') }
	res := code.eval_code('', out, 'text') or { panic('fmt output must evaluate: ${err}') }
	assert res.contains('hit'), 'fmt changed the match result: |${res}|'
}

fn test_fmt_fails_closed_on_shape_changing_spelling() {
	// The old colon-slot text parses (as bare atoms in argument position) but
	// its canonical emit reparses to a DIFFERENT shape — fmt must return the
	// input unchanged rather than bless the rewrite.
	src := '[?match :a :case :a :yield :ok]'
	out := code.fmt_source(src) or { panic('fmt: ${err}') }
	assert out == src, 'shape-changing spelling must fail closed to the input: |${out}|'
}

// ── #455: fmt lane agreement when a [; comment ] child precedes an attr ─────
// Comments are lexical trivia (lexicon.ebnf §1 [L3]); a bare `key=value` line
// after a `[; … ]` child is the same ATTRIBUTE it is without the comment.
// Pre-fix the data reader broke the attribute run at `[;`, so fmt_source's
// meaning-preservation check failed and the CLI fell back to the faithful
// PROGRAM formatter — dropping the comment and flipping every attr value to
// quoted style (`env="dev"`). With one parse the data formatter round-trips.
fn test_fmt_source_attr_after_comment_child_no_quote_flip() {
	src := '[config
 [; c ]
 env=dev
 [server host=localhost]
]'
	out := code.fmt_source(src) or { panic('fmt: ${err}') }
	assert out.contains('[; c ]'), 'fmt must preserve the comment; got: ${out}'
	assert out.contains('env=dev'), 'fmt must keep the bare attr spelling; got: ${out}'
	assert !out.contains('env="dev"'), 'no quoting-style flip (#455); got: ${out}'
	assert out.contains('host=localhost'), 'sibling attrs keep bare spelling; got: ${out}'
	// Idempotence: the fixed doc is a fmt fixpoint.
	twice := code.fmt_source(out) or { panic('fmt(fmt): ${err}') }
	assert out == twice, 'fmt must be idempotent on the fixed doc'
}

// ── #980: `cx fmt` is a fixed point across the CLI/LSP ROUND TRIP ────────────
// fmt_source returns UNTERMINATED text and the caller writes fmt(x) + '\n'
// back to the file, so the next pass is handed the TERMINATED text. The
// obligation is therefore fmt(fmt(x) + '\n') == fmt(x), byte-exactly.
//
// The fail-closed lanes used to return the source verbatim — trailing newline
// included — so `cx fmt` appended one newline per pass without bound.
// conformance/fmt.cxd's runner compares `strip_blank_edges` on both sides of
// its §7 check and could not see it; these assertions compare raw bytes.

fn assert_fmt_cli_cycle_stable(src string, label string) string {
	once := code.fmt_source(src) or { panic('fmt ${label}: ${err}') }
	assert !once.ends_with('\n'), 'fmt_source must return UNTERMINATED text (the caller supplies the newline); ${label} returned |${once}|'
	cycled := code.fmt_source(once + '\n') or { panic('fmt ${label} (cycle): ${err}') }
	assert cycled == once, 'fmt(fmt(x) + newline) != fmt(x) on ${label}:\n  once:   |${once}|\n  cycled: |${cycled}|'
	return once
}

// The minimal #980 repro, reduced mechanically from the corpus program below.
// `[?def …]` renders through the program emitter as a `:raw-source` carrier,
// which is not a re-parse fixed point, so faithful_program_fmt fails closed
// and hands back the source — the shape whose bytes used to grow.
fn test_fmt_cli_cycle_stable_on_fail_closed_def() {
	out := assert_fmt_cli_cycle_stable('[?def [f] 1]\n', 'minimal-980')
	assert out == '[?def [f] 1]', 'the fail-closed lane must return the source unchanged: |${out}|'
}

// The original #980 report: corpus/rosetta/21-fetch-csv-validate.cx grew
// 57 → 58 → 59 lines, one line per `cx fmt` pass. Pinned against the real
// file so a future lane change cannot reintroduce the growth on the exact
// input that found it.
fn test_fmt_cli_cycle_stable_on_the_reporting_corpus_program() {
	path := os.join_path(@VMODROOT, '..', 'corpus', 'rosetta', '21-fetch-csv-validate.cx')
	if !os.is_file(path) {
		return // corpus/ is not shipped in every checkout profile
	}
	src := os.read_file(path) or { panic('read ${path}: ${err}') }
	out := assert_fmt_cli_cycle_stable(src, '21-fetch-csv-validate.cx')
	// fmt is a NO-OP on this file (the fail-closed lane returns the source),
	// so the bytes `cx fmt` would write back are the bytes already on disk.
	assert out + '\n' == src, 'fmt must leave the corpus program byte-identical; got ${out.len + 1} bytes vs ${src.len}'
}

// ── source: vcx/tests/logfmt_test.v ──
// Tests for v3.4 logfmt mode. Spec: spec/grammar.ebnf [2].
// A document consisting entirely of top-level Name=Value attributes
// parses as a single synthetic Element named '_' carrying those
// attributes.
// ── Basic logfmt parsing ─────────────────────────────────────────────────────

fn test_logfmt_single_attr() {
	doc := cx.parse('time=2026-05-06T12:00:00Z') or { panic(err) }
	assert doc.elements.len == 1
	root := doc.root() or { panic('no root') }
	assert root.name == '_'
	assert root.attr('time') == '2026-05-06T12:00:00Z'
}

fn test_logfmt_multiple_attrs() {
	src := 'time=2026-05-06T12:00:00Z level=INFO svc=web req=GET path=/foo'
	doc := cx.parse(src) or { panic(err) }
	root := doc.root() or { panic('no root') }
	assert root.name == '_'
	assert root.attr('level') == 'INFO'
	assert root.attr('svc') == 'web'
	assert root.attr('req') == 'GET'
	assert root.attr('path') == '/foo'
}

fn test_logfmt_with_typed_values() {
	src := 'level=INFO count=42 active=true ratio=1.5'
	doc := cx.parse(src) or { panic(err) }
	root := doc.root() or { panic('no root') }
	assert root.attr('level') == 'INFO'
	assert root.attr('count') == '42'
	assert root.attr('active') == 'true'
	assert root.attr('ratio') == '1.5'
}

fn test_logfmt_with_quoted_value() {
	src := "msg='request completed' status=ok"
	doc := cx.parse(src) or { panic(err) }
	root := doc.root() or { panic('no root') }
	assert root.attr('msg') == 'request completed'
	assert root.attr('status') == 'ok'
}

// ── Disambiguation: regular CX still works ───────────────────────────────────

fn test_regular_cx_not_treated_as_logfmt() {
	// Starts with `[`, so it's a normal element document.
	doc := cx.parse('[server host=localhost]') or { panic(err) }
	root := doc.root() or { panic('no root') }
	assert root.name == 'server'
	assert root.attr('host') == 'localhost'
}

fn test_regular_cx_with_prolog_not_logfmt() {
	src := '[?cx version=3.4]
[server host=localhost]'
	doc := cx.parse(src) or { panic(err) }
	root := doc.root() or { panic('no root') }
	assert root.name == 'server'
}

// ── Comments + logfmt ────────────────────────────────────────────────────────

fn test_logfmt_with_leading_comment() {
	src := '# log line for the API
time=2026-05-06T12:00:00Z level=INFO'
	doc := cx.parse(src) or { panic(err) }
	root := doc.root() or { panic('no root') }
	assert root.name == '_'
	assert root.attr('level') == 'INFO'
}

// ── Multi-line logfmt (one synthetic element per record per Phase 7.56) ─────
//
// Per spec/grammar.ebnf §9 (and Phase 7.56 of branch native-data-binding),
// each newline-terminated record in a logfmt document produces its own
// synthetic [_ ...] element. The old single-element-merged behavior was
// dropped because last-write-wins on duplicate keys silently lost data
// for streams of many records.

fn test_logfmt_one_element_per_record() {
	src := 'time=2026-05-06T12:00:00Z level=INFO
time=2026-05-06T12:00:01Z level=WARN
time=2026-05-06T12:00:02Z level=ERROR'
	doc := cx.parse(src) or { panic(err) }
	assert doc.elements.len == 3, 'expected 3 synthetic elements, got ${doc.elements.len}'
	first := doc.elements[0] as cx.Element
	second := doc.elements[1] as cx.Element
	third := doc.elements[2] as cx.Element
	assert first.name == '_'
	assert first.attr('level') == 'INFO'
	assert second.attr('level') == 'WARN'
	assert third.attr('level') == 'ERROR'
}

// ── Empty input is not logfmt ────────────────────────────────────────────────

fn test_empty_input_no_logfmt() {
	doc := cx.parse('') or { panic(err) }
	assert doc.elements.len == 0
}

fn test_whitespace_only_input_no_logfmt() {
	doc := cx.parse('   \n\n  \t  ') or { panic(err) }
	assert doc.elements.len == 0
}

// ── source: vcx/tests/lossless_examples_matrix_test.v ──
// lossless_examples_matrix_test.v — #475: the examples/*.cx corpus as an
// end-to-end lossless-structure matrix (conversions.md §2.2.1 / §2.3.1).
//
// Every top-level example that parses as a DATA document (strict canonical
// accepts it) must round-trip CX → json|yaml (--lossless) → CX
// strict-canonical-identically through the registry — the same
// convert_by_name path the CLI uses. Program sources the data/canonical
// parser rejects (code-tour.cx, cxpath-tour.cx, match-multi.cx,
// modify-crud.cx) are skipped by the same criterion the CLI applies: they
// are programs, and program directives are outside every conversion lane's
// lossless domain (§0.2).

fn examples_dir() string {
	// tests run with cwd = vcx/ (v test vcx/tests/...); the corpus lives at
	// the repo root
	mut dir := os.join_path(os.dir(@FILE), '..', '..', 'examples')
	return os.real_path(dir)
}

fn test_examples_roundtrip_matrix() {
	code.caps_set_all() // retain `code` so its init() registers the json parser
	dir := examples_dir()
	assert os.is_dir(dir), 'examples corpus not found at ${dir}'
	mut files := os.ls(dir) or { panic('ls ${dir}: ${err}') }
	files.sort()
	mut covered := 0
	mut skipped := []string{}
	for f in files {
		if !f.ends_with('.cx') {
			continue
		}
		path := os.join_path(dir, f)
		if !os.is_file(path) {
			continue
		}
		src := os.read_file(path) or { panic('read ${path}: ${err}') }
		orig := cx.cx_text_canonical(src) or {
			skipped << f // program source — not a data document
			continue
		}
		for lane in ['json', 'yaml'] {
			emitted := cx.convert_by_name(src, 'cx', lane, true) or {
				assert false, '${f} ${lane}: lossless emit failed: ${err}'
				return
			}
			back := cx.convert_by_name(emitted, lane, 'cx', false) or {
				assert false, '${f} ${lane}: import failed: ${err}'
				return
			}
			got := cx.cx_text_canonical(back) or {
				assert false, '${f} ${lane}: recovered text not canonicalizable: ${err}\n${back}'
				return
			}
			assert got == orig, '${f} ${lane}: round-trip not strict-canonical-eq'
		}
		covered++
	}
	// the corpus has 15 data documents today; guard against silent shrinkage
	assert covered >= 15, 'examples matrix shrank: only ${covered} data docs round-tripped (skipped: ${skipped})'
}

// ── source: vcx/tests/lossless_xml_test.v ──
// v0.8.0 — `--lossless` XML (conversions.md §0.2) + the CXLS007 ambiguous
// string-list warning premise.
//
// (a) emit_xml_lossless tags each typed scalar with its `<cx:T>` carrier so the
//     XML→CX round-trip is faithful, WITHOUT changing the idiomatic (default)
//     form. The headline case: adjacent string items `[x "a" "b"]` keep their
//     boundary as `<cx:string>` carriers (the default collapses them to `ab`).
// (b) the LSP CXLS007 warning fires on a cx_element body with ≥2 adjacent
//     QUOTED-string items; this test pins the parse_program shape the detector
//     relies on (and that the comma form is distinct → no false positive).

fn lossless_xml(src string) string {
	return cx.to_xml_lossless(src) or { panic('to_xml_lossless: ${err}') }
}

fn default_xml(src string) string {
	return cx.to_xml(src) or { panic('to_xml: ${err}') }
}

// ── (a) the default (lossy) form is UNCHANGED ────────────────────────────────

fn test_default_unchanged_single_scalar() {
	assert default_xml('[x 1]') == '<x>1</x>'
	assert default_xml('[x :ok]') == '<x>ok</x>'
	assert default_xml('[d 2024-01-15]') == '<d>2024-01-15</d>'
}

fn test_default_unchanged_string_list_collapses() {
	// The idiomatic form collapses adjacent strings (documented, accepted).
	assert default_xml('[x "a" "b"]') == '<x>ab</x>'
}

fn test_default_unchanged_prose() {
	assert default_xml('[p the quick fox]') == '<p>the quick fox</p>'
}

fn test_default_unchanged_typed_list() {
	// Non-string scalars already carry `<cx:T>` in BOTH modes.
	assert default_xml('[x 1 2]') == '<x><cx:int>1</cx:int><cx:int>2</cx:int></x>'
}

// ── (a) lossless adds per-item `<cx:T>` carriers ─────────────────────────────

fn test_lossless_string_list_carriers() {
	// The headline case — adjacent string items keep their boundary.
	assert lossless_xml('[x "a" "b"]') == '<x><cx:string>a</cx:string><cx:string>b</cx:string></x>'
}

fn test_lossless_single_scalar_carrier() {
	assert lossless_xml('[x 1]') == '<x><cx:int>1</cx:int></x>'
	assert lossless_xml('[x :ok]') == '<x><cx:atom>ok</cx:atom></x>'
	assert lossless_xml('[d 2024-01-15]') == '<d><cx:date>2024-01-15</cx:date></d>'
}

fn test_lossless_single_string_stays_bare() {
	// A SINGLE string re-infers as string — no carrier needed (conversions.md
	// §0.2: string XML lossless = default).
	assert lossless_xml('[x hi]') == '<x>hi</x>'
}

fn test_lossless_prose_stays_bare() {
	assert lossless_xml('[p the quick fox]') == '<p>the quick fox</p>'
}

fn test_lossless_mixed_list() {
	assert lossless_xml('[mixed 1 "two" :three true]') == '<mixed><cx:int>1</cx:int><cx:string>two</cx:string><cx:atom>three</cx:atom><cx:bool>true</cx:bool></mixed>'
}

// ── (a) faithful round-trip: cx → lossless xml → cx-node ──────────────────────

fn body_item_count(src string) int {
	doc := cx.parse(src) or { panic('parse: ${err}') }
	for n in doc.elements {
		if n is cx.Element {
			return n.items.len
		}
	}
	return -1
}

fn roundtrip_item_count(src string) int {
	xml := lossless_xml(src)
	doc := cx.parse_xml(xml) or { panic('parse_xml: ${err}') }
	for n in doc.elements {
		if n is cx.Element {
			return n.items.len
		}
	}
	return -1
}

fn test_lossless_roundtrip_preserves_string_list_items() {
	// `[x "a" "b"]` is TWO string items; the lossless XML→CX round-trip must
	// preserve both (the default form would collapse them to one).
	assert body_item_count('[x "a" "b"]') == 2
	assert roundtrip_item_count('[x "a" "b"]') == 2
}

fn test_lossless_roundtrip_preserves_atom_type() {
	xml := lossless_xml('[x :ok]')
	doc := cx.parse_xml(xml) or { panic('parse_xml: ${err}') }
	mut found_atom := false
	for n in doc.elements {
		if n is cx.Element {
			for it in n.items {
				if it is cx.ScalarNode {
					if it.data_type == .atom_type {
						found_atom = true
					}
				}
			}
		}
	}
	assert found_atom, 'atom type lost on lossless XML round-trip'
}

// ── (b) CXLS007 detection premise — parse_program shape ──────────────────────

fn cx_element_items(src string) []cx.ProgramNode {
	prog := cx.parse_program(src) or { panic('parse_program: ${err}') }
	lit := prog.body as cx.ProgramLiteral
	assert lit.kind == .cx_element, 'expected cx_element, got ${lit.kind}'
	return lit.items
}

fn test_warning_premise_two_quoted_strings_are_adjacent_items() {
	// `[x "a" "b"]` → cx_element with two adjacent string_lit items, each whose
	// SOURCE position points at a quote. This is exactly what CXLS007 detects.
	src := '[x "a" "b"]'
	items := cx_element_items(src)
	assert items.len == 2
	mut quoted := 0
	for it in items {
		if it is cx.ProgramLiteral {
			if it.kind == .string_lit {
				c := src[it.pos.offset]
				if c == `"` || c == `'` {
					quoted++
				}
			}
		}
	}
	assert quoted == 2, 'expected 2 quoted string items, got ${quoted}'
}

fn test_warning_premise_comma_form_does_not_parse_as_program() {
	// `[x "a", "b"]` (the comma array) is NOT valid program-body syntax — a
	// top-level comma in element-body expression position is a parse error. So
	// CXLS007 (which runs on parse_program and bails on parse failure) can never
	// false-positive on the comma form; it only sees the no-comma ambiguous shape.
	if _ := cx.parse_program('[x "a", "b"]') {
		assert false, 'expected the comma array form to be a program parse error'
	}
}

fn test_warning_premise_single_quoted_string_is_not_flagged() {
	// A SINGLE quoted string is not ambiguous (no adjacent sibling) — exactly one
	// item, so the ≥2-run detector never triggers.
	items := cx_element_items('[x "a"]')
	assert items.len == 1
}

// ── source: vcx/tests/toml_lossless_test.v ──
// toml_lossless_test.v — #5: TOML imports LOSSLESSLY to the native value
// model (MapNode / ArrayNode / scalars), matching JSON/YAML — not the old
// synthesized-element shape (`[server [port 8080]]`). TOML tables → nested
// maps; arrays → Arrays; nested `[a.b]` tables → nested maps.

fn test_toml_table_imports_as_map() {
	doc := cx.parse_toml('[server]\nport = 8080\n') or { panic('parse_toml: ${err}') }
	assert doc.elements.len == 1, 'expected a single value root, got ${doc.elements.len}'
	root := doc.elements[0]
	assert root is cx.MapNode, 'top-level TOML must import as MapNode, got ${typeof(root).name}'
	out := cx.emit_cx(doc)
	assert out.contains('{server:'), 'expected lossless map {server: …}, got: ${out}'
	assert out.contains('port: 8080'), 'expected nested map value, got: ${out}'
	assert !out.contains('[server'), 'must NOT synthesize elements: ${out}'
}

fn test_toml_nested_table_and_array() {
	doc := cx.parse_toml('[server]\nhosts = ["a", "b"]\n[server.db]\nname = "main"\n') or {
		panic('parse_toml: ${err}')
	}
	out := cx.emit_cx(doc)
	assert out.contains("['a', 'b']") || out.contains('[a, b]'),
		'TOML array must import as an Array, got: ${out}'
	assert out.contains('db: {name:'), 'nested [server.db] table must be a nested map, got: ${out}'
}

// ── source: vcx/tests/yaml_lossless_test.v ──
// yaml_lossless_test.v — #4: YAML imports LOSSLESSLY to the native value
// model (MapNode / ArrayNode / scalars), matching the JSON codec — not the
// old synthesized-element shape (`[server [port 8080]]`). A mapping is a Map,
// a sequence is an Array, and the read round-trips through canonical CX / YAML.

fn test_yaml_mapping_imports_as_map() {
	doc := cx.parse_yaml('server:\n  port: 8080\n') or { panic('parse_yaml: ${err}') }
	assert doc.elements.len == 1, 'expected a single value root, got ${doc.elements.len}'
	root := doc.elements[0]
	assert root is cx.MapNode, 'top-level mapping must import as MapNode, got ${typeof(root).name}'
	out := cx.emit_cx(doc)
	assert out.contains('{server:'), 'expected lossless map {server: …}, got: ${out}'
	assert out.contains('port: 8080'), 'expected nested map value, got: ${out}'
	assert !out.contains('[server'), 'must NOT synthesize elements: ${out}'
}

fn test_yaml_sequence_imports_as_array() {
	doc := cx.parse_yaml('hosts:\n  - a\n  - b\n') or { panic('parse_yaml: ${err}') }
	root := doc.elements[0]
	assert root is cx.MapNode, 'mapping root expected'
	out := cx.emit_cx(doc)
	assert out.contains("['a', 'b']") || out.contains('[a, b]'),
		'YAML sequence must import as an Array, got: ${out}'
}

// #412: a block sequence of mappings (`- k: v` with continuation keys on the
// following lines) imports each item as a complete Map — not a one-line
// scalar with the remaining keys hoisted onto the parent and later items
// dropped.
fn test_yaml_block_seq_of_mappings() {
	src := 'books:\n  - title: A\n    year: 1\n  - title: B\n    year: 2\n'
	doc := cx.parse_yaml(src) or { panic('parse_yaml: ${err}') }
	out := cx.emit_cx(doc)
	assert out.contains('{title: A, year: 1}'), 'item 1 must keep all keys, got: ${out}'
	assert out.contains('{title: B, year: 2}'), 'item 2 must not be dropped, got: ${out}'
	assert !out.contains("'title: A'"), 'compact mapping must not import as a scalar: ${out}'
}

// #412 adjacent shape: `- - x` — a block sequence of block sequences.
fn test_yaml_block_seq_of_seqs() {
	doc := cx.parse_yaml('- - a\n  - b\n- - c\n') or { panic('parse_yaml: ${err}') }
	out := cx.emit_cx(doc)
	assert out.contains("[['a', 'b'], ['c']]"), 'seq of seqs must nest, got: ${out}'
}

// Cross-format: a YAML mapping and the equivalent JSON import to the SAME
// canonical CX (the shared lossless map model — resolves #4's divergence).
fn test_yaml_json_import_agree() {
	yaml_doc := cx.parse_yaml('a: 1\nb: two\n') or { panic('parse_yaml: ${err}') }
	yaml_cx := cx.emit_cx(yaml_doc)
	assert yaml_cx.contains('{a: 1') && yaml_cx.contains('b: two'),
		'YAML import not the lossless map model: ${yaml_cx}'
}

// ── source: vcx/tests/include_test.v ──
// Tests for the `[?cx include=PATH]` lexical-inclusion resolver
// (spec/code.md §13; engine vcx/cx/include.v). Covers the contract:
// splice semantics, path resolution, traversal reject, URL reject,
// cycle detection, depth limit, error mapping E901-E911, and the
// no-resolution default (directive preserved when no root supplied).
//
// History (#421): this file originally shipped with the GG1 resolver and
// was collaterally deleted in the phase-7 POC cleanup (65723b44) although
// the resolver itself stayed in production and code.md §13 is approved
// spec. Restored (minus the retired CXL eval-time `[?include]` section)
// so the resolver has live V regression coverage again.

fn tmp_dir(label string) string {
	dir := os.join_path(os.temp_dir(), 'cx_include_${label}_${os.getpid()}')
	os.rmdir_all(dir) or {}
	os.mkdir_all(dir) or { panic('mkdir ${dir}: ${err}') }
	return dir
}

fn write_file(dir string, name string, content string) string {
	full := os.join_path(dir, name)
	os.mkdir_all(os.dir(full)) or {}
	os.write_file(full, content) or { panic('write ${full}: ${err}') }
	return full
}

// ── Splice semantics ────────────────────────────────────────────────────

fn test_include_splices_top_level_elements() {
	root := tmp_dir('splice_basic')
	defer { os.rmdir_all(root) or {} }
	write_file(root, 'defaults.cx', '[server host=localhost]\n[server host=backup]')
	main := '[config\n  [?cx include=defaults.cx]\n  [client retries=3]\n]'
	doc := cx.parse_with_include_root(main, root) or {
		panic('parse_with_include_root: ${err}')
	}
	assert doc.elements.len == 1, 'expected 1 root, got ${doc.elements.len}'
	config := doc.elements[0] as cx.Element
	// After splice: 3 children — two servers + the trailing client.
	assert config.items.len == 3, 'expected 3 items after splice, got ${config.items.len}'
}

fn test_include_no_root_preserves_directive() {
	// Empty root → no resolution; directive remains in AST as prolog
	// node (top-level [?cx ...] parses into doc.prolog per
	// is_prolog_node_type, parser.v:544).
	root := tmp_dir('no_root')
	defer { os.rmdir_all(root) or {} }
	write_file(root, 'a.cx', '[a]')
	doc := cx.parse_with_include_root('[?cx include=a.cx]', '') or {
		panic('parse: ${err}')
	}
	assert doc.prolog.len == 1, 'expected directive in prolog, got ${doc.prolog.len}'
	first := doc.prolog[0]
	assert first is cx.CXDirectiveNode, 'expected CXDirectiveNode, got: ${first.type_name()}'
}

fn test_include_nested_resolution() {
	root := tmp_dir('nested')
	defer { os.rmdir_all(root) or {} }
	write_file(root, 'leaf.cx', '[leaf v=1]')
	write_file(root, 'mid.cx', '[mid\n  [?cx include=leaf.cx]\n]')
	doc := cx.parse_with_include_root('[?cx include=mid.cx]', root) or {
		panic('${err}')
	}
	assert doc.elements.len == 1
	mid := doc.elements[0] as cx.Element
	assert mid.name == 'mid'
	assert mid.items.len == 1
	leaf := mid.items[0] as cx.Element
	assert leaf.name == 'leaf'
}

// ── Path resolution + reject paths ──────────────────────────────────────

fn test_include_e901_absolute_path_rejected() {
	root := tmp_dir('e901')
	defer { os.rmdir_all(root) or {} }
	cx.parse_with_include_root('[?cx include=/etc/passwd]', root) or {
		assert err.msg().contains('E901'), 'expected E901, got: ${err.msg()}'
		return
	}
	assert false, 'expected E901 reject'
}

fn test_include_e902_traversal_rejected() {
	root := tmp_dir('e902')
	defer { os.rmdir_all(root) or {} }
	// Try to reach a sibling-of-root file via `../`. Resolved path
	// escapes root → E902.
	cx.parse_with_include_root('[?cx include=../sibling.cx]', root) or {
		assert err.msg().contains('E902'), 'expected E902, got: ${err.msg()}'
		return
	}
	assert false, 'expected E902 reject'
}

fn test_include_e903_url_scheme_rejected() {
	root := tmp_dir('e903')
	defer { os.rmdir_all(root) or {} }
	cases := ["[?cx include='http://evil.com/a.cx']", "[?cx include='file:///etc/passwd']"]
	for src in cases {
		cx.parse_with_include_root(src, root) or {
			assert err.msg().contains('E903'), 'expected E903 for ${src}, got: ${err.msg()}'
			continue
		}
		assert false, 'expected E903 reject for ${src}'
	}
}

fn test_include_e904_cycle_detected() {
	root := tmp_dir('e904')
	defer { os.rmdir_all(root) or {} }
	// Self-include cycle.
	write_file(root, 'loop.cx', '[?cx include=loop.cx]')
	cx.parse_with_include_root('[?cx include=loop.cx]', root) or {
		assert err.msg().contains('E904'), 'expected E904, got: ${err.msg()}'
		return
	}
	assert false, 'expected E904 cycle'
}

fn test_include_e905_max_depth_exceeded() {
	root := tmp_dir('e905')
	defer { os.rmdir_all(root) or {} }
	// Chain a-1.cx → a-2.cx → ... → a-10.cx; max depth 8 should fire.
	for i in 1 .. 10 {
		next := 'a-${i + 1}.cx'
		write_file(root, 'a-${i}.cx', '[?cx include=${next}]')
	}
	write_file(root, 'a-10.cx', '[leaf]')
	cx.parse_with_include_root('[?cx include=a-1.cx]', root) or {
		assert err.msg().contains('E905'), 'expected E905, got: ${err.msg()}'
		return
	}
	assert false, 'expected E905 depth limit'
}

fn test_include_e906_not_found() {
	root := tmp_dir('e906')
	defer { os.rmdir_all(root) or {} }
	cx.parse_with_include_root('[?cx include=nonexistent.cx]', root) or {
		assert err.msg().contains('E906'), 'expected E906, got: ${err.msg()}'
		return
	}
	assert false, 'expected E906 not-found'
}

fn test_include_e908_directory_rejected() {
	root := tmp_dir('e908')
	defer { os.rmdir_all(root) or {} }
	os.mkdir_all(os.join_path(root, 'subdir')) or {}
	cx.parse_with_include_root('[?cx include=subdir]', root) or {
		assert err.msg().contains('E908'), 'expected E908, got: ${err.msg()}'
		return
	}
	assert false, 'expected E908 directory reject'
}

fn test_include_e911_inner_parse_fail() {
	root := tmp_dir('e911')
	defer { os.rmdir_all(root) or {} }
	write_file(root, 'broken.cx', '[unterminated')
	cx.parse_with_include_root('[?cx include=broken.cx]', root) or {
		assert err.msg().contains('E911'), 'expected E911, got: ${err.msg()}'
		return
	}
	assert false, 'expected E911 inner parse fail'
}

// ── Diamond include (legal per spec §6) ─────────────────────────────────

fn test_include_diamond_legal() {
	root := tmp_dir('diamond')
	defer { os.rmdir_all(root) or {} }
	write_file(root, 'leaf.cx', '[leaf v=42]')
	write_file(root, 'b.cx', '[b [?cx include=leaf.cx]]')
	write_file(root, 'c.cx', '[c [?cx include=leaf.cx]]')
	main := '[doc\n  [?cx include=b.cx]\n  [?cx include=c.cx]\n]'
	doc := cx.parse_with_include_root(main, root) or {
		panic('diamond failed: ${err}')
	}
	root_doc := doc.elements[0] as cx.Element
	assert root_doc.items.len == 2
	b := root_doc.items[0] as cx.Element
	c := root_doc.items[1] as cx.Element
	assert b.name == 'b'
	assert c.name == 'c'
	assert b.items.len == 1
	assert c.items.len == 1
}

// ── Splice rules: discard XMLDecl / CXDirective at included top level ───

fn test_include_discards_xmldecl_at_top_level() {
	root := tmp_dir('xmldecl')
	defer { os.rmdir_all(root) or {} }
	write_file(root, 'inc.cx', "[?xml version='1.0']\n[real-element]")
	main := '[?cx include=inc.cx]'
	doc := cx.parse_with_include_root(main, root) or { panic('${err}') }
	// Only the real element is spliced; the XMLDecl is discarded.
	assert doc.elements.len == 1
	real := doc.elements[0] as cx.Element
	assert real.name == 'real-element'
}

// U7 — real-sandbox regression. Per spec/v0_7_0_status.md U7 + GG1:
// the ?include resolver MUST reject paths that escape the include
// root even when the target file exists on disk. Creates the
// sibling file explicitly so the failure-mode is "traversal
// rejected by sandbox" rather than "E906 file-not-found".

fn test_u7_real_sandbox_rejects_existing_sibling_via_traversal() {
	parent := os.join_path(os.temp_dir(), 'cx_u7_real_${os.getpid()}')
	os.rmdir_all(parent) or {}
	os.mkdir_all(parent) or { panic(err) }
	defer { os.rmdir_all(parent) or {} }
	// Create a "secret" file as a SIBLING of the include root.
	os.write_file(os.join_path(parent, 'secret.cx'), '[secret content]') or { panic(err) }
	// The include root is a subdir of parent; ../secret.cx escapes
	// the root and must be rejected as E902 even though the target
	// file exists.
	root := os.join_path(parent, 'allowed')
	os.mkdir_all(root) or { panic(err) }
	cx.parse_with_include_root('[?cx include=../secret.cx]', root) or {
		assert err.msg().contains('E902'),
			'U7 sandbox breach: expected E902 traversal-rejected, got: ${err.msg()}'
		return
	}
	assert false, 'U7 sandbox breach: ?include of ../secret.cx succeeded'
}

fn test_u7_real_sandbox_admits_in_tree_include() {
	// Companion to the negative case: a legitimate in-tree include
	// works. Confirms the sandbox isn't refusing everything.
	root := tmp_dir('u7_admits')
	defer { os.rmdir_all(root) or {} }
	write_file(root, 'allowed.cx', '[allowed flag=ok]')
	doc := cx.parse_with_include_root('[?cx include=allowed.cx]', root) or {
		panic('legitimate in-tree include should resolve: ${err}')
	}
	assert doc.elements.len == 1
	el := doc.elements[0] as cx.Element
	assert el.name == 'allowed'
}

// ── source: vcx/tests/text_surgery_test.v ──
// text_surgery_test.v — #93: in-CX surgical text edits (so cx is viable for the
// whitespace-exact replacements we used to drop to Python/sed for).
//   strings:replace-exactly — fail-loud unless `from` occurs exactly once.
//   io:edit-file            — read → replace-exactly → write (atomic, gated).

fn cx_bin_ts() string {
	return testenv.cx_bin()
}

fn run_ts(src string, allow bool) os.Result {
	f := os.join_path(os.temp_dir(), 'cx_ts_${os.getpid()}_${src.len}.cx')
	os.write_file(f, src) or { panic('write: ${err}') }
	defer { os.rm(f) or {} }
	cap := if allow { '--allow-all ' } else { '' }
	return os.execute('${cx_bin_ts()} ${cap}${f}')
}

// ── strings:replace-exactly ──────────────────────────────────────────────────

fn test_replace_exactly_unique() {
	r := run_ts("[?lib 'cx-stdlib/strings'] [\$strings:replace-exactly \"a.b.c\" \"b\" \"X\"]", false)
	assert r.output.trim_space() == "'a.X.c'", 'unique replace wrong: ${r.output}'
}

fn test_replace_exactly_ambiguous_errs() {
	r := run_ts("[?lib 'cx-stdlib/strings'] [\$strings:replace-exactly \"a.a.a\" \"a\" \"X\"]", false)
	assert r.output.contains('CXER2903'), 'ambiguous should err CXER2903: ${r.output}'
	assert r.output.contains('found 3'), 'should report the count: ${r.output}'
}

fn test_replace_exactly_missing_errs() {
	r := run_ts("[?lib 'cx-stdlib/strings'] [\$strings:replace-exactly \"abc\" \"z\" \"X\"]", false)
	assert r.output.contains('CXER2903'), 'missing target should err CXER2903: ${r.output}'
	assert r.output.contains('found 0'), 'should report zero matches: ${r.output}'
}

// ── io:edit-file ─────────────────────────────────────────────────────────────

fn test_edit_file_real_edit() {
	target := os.join_path(os.temp_dir(), 'cx_ts_edit_${os.getpid()}.txt')
	os.write_file(target, 'hello OLD world') or { panic(err) }
	defer { os.rm(target) or {} }
	r := run_ts("[?lib 'cx-stdlib/io'] [\$io:edit-file \"${target}\" \"OLD\" \"NEW\"]", true)
	assert r.exit_code == 0, 'edit-file errored: ${r.output}'
	got := os.read_file(target) or { panic(err) }
	assert got == 'hello NEW world', 'file not edited correctly: "${got}"'
}

fn test_edit_file_ambiguous_does_not_write() {
	// `from` occurs twice → CXER2903 and the file must be left UNCHANGED.
	target := os.join_path(os.temp_dir(), 'cx_ts_noedit_${os.getpid()}.txt')
	os.write_file(target, 'x and x') or { panic(err) }
	defer { os.rm(target) or {} }
	r := run_ts("[?lib 'cx-stdlib/io'] [\$io:edit-file \"${target}\" \"x\" \"Y\"]", true)
	assert r.output.contains('CXER2903'), 'ambiguous edit-file should err: ${r.output}'
	got := os.read_file(target) or { panic(err) }
	assert got == 'x and x', 'file must be unchanged on a failed edit, got: "${got}"'
}

fn test_edit_file_cap_denied() {
	target := os.join_path(os.temp_dir(), 'cx_ts_cap_${os.getpid()}.txt')
	os.write_file(target, 'old') or { panic(err) }
	defer { os.rm(target) or {} }
	r := run_ts("[?lib 'cx-stdlib/io'] [\$io:edit-file \"${target}\" \"old\" \"new\"]", false)
	assert r.output.contains('CXER0271'), 'no caps → CXER0271 expected: ${r.output}'
	got := os.read_file(target) or { panic(err) }
	assert got == 'old', 'cap-denied edit must not touch the file: "${got}"'
}

