	events := cx.stream('[config host=localhost]') or { panic(err) }
	type_names := events.map(match it {
		cx.StreamStartDoc     { 'StartDoc' }
		cx.StreamEndDoc       { 'EndDoc' }
		cx.StreamStartElement { 'StartElement' }
		cx.StreamEndElement   { 'EndElement' }
		else                  { 'Other' }
