	assert 'StartDoc' in type_names
	assert 'StartElement' in type_names
	assert 'EndDoc' in type_names
}

// ── source: vcx/tests/data_program_seam_test.v ──
// v0.8.0 DATA↔PROGRAM SEAM CLOSURE.
//
// `cx <file>` defaults to EVAL (the program reading; CLI-default=eval). The
// program reader previously FORKED from / REJECTED three pure-DATA
// constructs, so the new default could mishandle valid data files:
//   - `[#…#]` raw text was wrongly eaten as a block comment and DISCARDED
//     (a spec-conformance bug vs code.md §1.3 / lexicon [L2]/[L3]),
//   - `&…;` entity / `&#…;` char references hit the lexer's unexpected-char
//     catch-all,
//   - `[!…]` declarations + `[!DOCTYPE …]` were rejected (`!` in expression
//     position).
//
// Closure adds ONE `node_lit` ProgramLiteralKind: the program lexer captures
// the data-construct SPAN as a `data_span` token and the parser delegates to
// the proven data reader (`cx.parse_data_node`), carrying the parsed
// `cx.Node`. Eval returns it as-is. The "data = a program that evaluates to
// itself" invariant therefore holds BY CONSTRUCTION — the program (eval)
// reading of these constructs IS the data reading.
//
// `[-` (block-comment-vs-subtraction) stays a by-design fork (out of scope,
// like SEQ-NEST).

// data_read renders the DATA reading of src (what `cx --from=cx --to=cx`
// produces): parse as data, emit canonical CX.
fn data_read(src string) string {
	doc := cx.parse(src) or { panic('data parse failed: ${err}') }
	return cx.emit_cx(doc).trim_space()
}

// eval_read renders the PROGRAM (eval) reading of src (what `cx <file>`
// produces by default): parse as a program, evaluate, render to CX.
fn eval_read(src string) string {
	return code.eval_code('', src, 'cx') or { panic('eval failed: ${err}') }.trim_space()
}

// ── 1. parse_data_node returns the right node kind for each construct ─────────

fn test_parse_data_node_raw() {
	n := cx.parse_data_node('[# hello #]') or {
		assert false, 'parse_data_node failed: ${err}'
		return
	}
	assert n is cx.RawTextNode, 'expected RawTextNode'
	assert (n as cx.RawTextNode).value == ' hello ', 'raw value mismatch: "${(n as cx.RawTextNode).value}"'
}

fn test_parse_data_node_entity() {
	n := cx.parse_data_node('&amp;') or {
		assert false, 'parse_data_node failed: ${err}'
		return
	}
	assert n is cx.EntityRefNode, 'expected EntityRefNode'
	assert (n as cx.EntityRefNode).name == 'amp'
}

fn test_parse_data_node_charref() {
	n := cx.parse_data_node('&#65;') or {
		assert false, 'parse_data_node failed: ${err}'
		return
	}
	// A char reference resolves to text (codepoint 65 = 'A').
	assert n is cx.TextNode, 'expected TextNode'
	assert (n as cx.TextNode).value == 'A'
}

fn test_parse_data_node_entity_decl() {
	n := cx.parse_data_node("[!ENTITY x 'y']") or {
		assert false, 'parse_data_node failed: ${err}'
		return
	}
	assert n is cx.EntityDeclNode, 'expected EntityDeclNode'
}

fn test_parse_data_node_doctype() {
	n := cx.parse_data_node('[!DOCTYPE foo]') or {
		assert false, 'parse_data_node failed: ${err}'
		return
	}
	assert n is cx.DoctypeDecl, 'expected DoctypeDecl'
	assert (n as cx.DoctypeDecl).name == 'foo'
}

fn test_parse_data_node_rejects_trailing() {
	if _ := cx.parse_data_node('[# a #] [# b #]') {
		assert false, 'expected error on two-node input'
	}
}

// ── 2. The program lexer/parser builds a node_lit literal ─────────────────────

fn test_program_parse_node_lit() {
	prog := cx.parse_program('[# raw #]') or {
		assert false, 'program parse failed: ${err}'
		return
	}
	lit := prog.body as cx.ProgramLiteral
	assert lit.kind == .node_lit, 'expected node_lit, got ${lit.kind}'
	assert lit.str_val == '[# raw #]', 'verbatim span not preserved: "${lit.str_val}"'
	carried := lit.node or {
		assert false, 'node_lit carries no node'
		return
	}
	assert carried is cx.RawTextNode
}

// ── 3. The SEAM: eval reading == data reading for valid placements ───────────
//
// Raw text and entity references are valid ELEMENT-BODY content; declarations
// and DOCTYPE are valid as STANDALONE (prolog-position) nodes. For every one
// of these the eval reading must equal the data reading byte-for-byte.

fn test_seam_raw_in_body() {
	src := '[doc [# r #]]'
	assert eval_read(src) == data_read(src), 'raw-in-body seam: eval="${eval_read(src)}" data="${data_read(src)}"'
}

fn test_seam_entity_in_body() {
	src := '[p &amp;]'
	assert eval_read(src) == data_read(src), 'entity-in-body seam: eval="${eval_read(src)}" data="${data_read(src)}"'
}

fn test_seam_two_raws_in_body() {
	src := '[doc [# a #] [# b #]]'
	assert eval_read(src) == data_read(src), 'two-raws seam: eval="${eval_read(src)}" data="${data_read(src)}"'
}

fn test_seam_raw_standalone() {
	src := '[# hi #]'
	assert eval_read(src) == data_read(src), 'raw-standalone seam: eval="${eval_read(src)}" data="${data_read(src)}"'
}

fn test_seam_entity_standalone() {
	src := '&amp;'
	assert eval_read(src) == data_read(src), 'entity-standalone seam: eval="${eval_read(src)}" data="${data_read(src)}"'
}

fn test_seam_entity_decl_standalone() {
	src := "[!ENTITY x 'y']"
	assert eval_read(src) == data_read(src), 'entity-decl seam: eval="${eval_read(src)}" data="${data_read(src)}"'
}

fn test_seam_element_decl_standalone() {
	src := '[!ELEMENT a EMPTY]'
	assert eval_read(src) == data_read(src), 'element-decl seam: eval="${eval_read(src)}" data="${data_read(src)}"'
}

fn test_seam_doctype_standalone() {
	src := '[!DOCTYPE foo]'
	assert eval_read(src) == data_read(src), 'doctype seam: eval="${eval_read(src)}" data="${data_read(src)}"'
}

fn test_seam_doctype_with_internal_subset() {
	src := "[!DOCTYPE foo [ [!ENTITY x 'y'] ]]"
	assert eval_read(src) == data_read(src), 'doctype-subset seam: eval="${eval_read(src)}" data="${data_read(src)}"'
}

fn test_seam_decl_quote_with_bracket() {
	// A `]` inside a quoted literal must NOT close the `[!…]` span early
	// (the lexer skips quoted literals while tracking bracket depth).
	src := "[!ENTITY x 'a]b']"
	assert eval_read(src) == data_read(src), 'decl-]-in-string seam: eval="${eval_read(src)}" data="${data_read(src)}"'
}

// ── 4. The original bug: raw text is no longer DISCARDED by eval ──────────────

fn test_raw_no_longer_discarded() {
	// Before the fix, `cx file.cx` (eval) returned `[doc]` (raw eaten as a
	// comment). It must now preserve the raw text.
	assert eval_read('[doc [# r #]]') == '[doc [# r #]]'
}

// ── 5. `[--…--]` stays a comment (NOT captured as a data_span) ────────────────

fn test_semicolon_block_comment() {
	// `[; … ]` is the block comment and is skipped by the lexer; the
	// surrounding element evaluates with the comment elided.
	assert eval_read('[doc [; a comment ] 1]') == '[doc 1]'
}

// ── The §3.10.3 columnar lattice rise (I5-s17 W3, L89) ───────────────
// Typed 0x60 payloads (no per-cell tags); unsigned + f16/f32 widths
// KEPT; decimal/bigint column codes; bit-packed bool; 0x80 nullable;
// 0x81 mixed (the honest escape — never a silent string).

fn lat_roundtrip(src string) string {
	doc := cx.parse(src) or { panic(err) }
	bin := cx.emit_data_bin(doc) or { panic('emit: ${err}') }
	doc2 := cx.parse_data_bin(bin) or { panic('decode: ${err}') }
	return cx.emit_cx(doc2)
}

fn test_lattice_unsigned_and_float_widths_kept() {
	src := '[m [t [table[a::u16 b::u64 c::f32]]\n  1 9 1.5e0\n  2 8 2.5e0\n]]\n'
	out := lat_roundtrip(src)
	// The column TYPES survive (narrowest-within-kind — never erased
	// by promotion) and the values round-trip.
	assert out.contains('a::u16'), out
	assert out.contains('b::u64'), out
	assert out.contains('c::f32'), out
	assert out.contains('1.5'), out
}

fn test_lattice_decimal_bigint_columns() {
	src := '[m [t [table[p::decimal q::bigint]]\n  19.99 123456789012345678901\n  8.50 7\n]]\n'
	out := lat_roundtrip(src)
	assert out.contains('p::decimal'), out
	assert out.contains('q::bigint'), out
	assert out.contains('19.99'), out
	assert out.contains('123456789012345678901'), out
}

fn test_lattice_bool_bitpacked_roundtrip() {
	src := '[m [t [table[on::bool]]\n  true\n  false\n  true\n]]\n'
	out := lat_roundtrip(src)
	assert out.contains('on::bool'), out
	assert out.contains('true'), out
	assert out.contains('false'), out
}

fn test_lattice_nullable_wrapper() {
	// A typed column with nulls wraps 0x80 (bitmap + packed non-nulls)
	// and round-trips null positions exactly.
	src := '[m [t [table[n::int]]\n  1\n  null\n  3\n]]\n'
	out := lat_roundtrip(src)
	assert out.contains('null'), out
	assert out.contains('1'), out
	assert out.contains('3'), out
}

fn test_lattice_f16_column_roundtrip() {
	src := '[m [t [table[h::f16]]\n  1.5e0\n  -2.0e0\n]]\n'
	out := lat_roundtrip(src)
	assert out.contains('h::f16'), out
	assert out.contains('1.5'), out
	assert out.contains('-2'), out
}

fn test_lattice_atom_column_dictionary_by_construction() {
	// L89: atom columns dictionary-encode BY CONSTRUCTION (the 0x62
	// form). Transparency is the assertion: the round-trip render is
	// IDENTICAL to the direct render. (The canonical TEXT lane's own
	// atom-cell quoting is #794 — the wire is transparent to it.)
	src := '[m [t [table[status::atom]]\n  :ok\n  :err\n  :ok\n  :ok\n]]\n'
	doc := cx.parse(src) or { panic(err) }
	direct := cx.emit_cx(doc)
	bin := cx.emit_data_bin(doc) or { panic('emit: ${err}') }
	doc2 := cx.parse_data_bin(bin) or { panic('decode: ${err}') }
	out := cx.emit_cx(doc2)
	assert out == direct, 'round-trip must equal direct render\ndirect:\n${direct}\ngot:\n${out}'
	assert out.contains('status::atom'), out
}

fn test_lattice_nullable_keeps_declared_width() {
	// #807/AF-2(b) family: the 0x60 nullable wrapper's inner code is
	// the DECLARED width (u16 here — never the value-derived int64
	// widening), and the decode REFINES the rendered column type from
	// that inner code (u::u16, never bare u).
	src := '[m [t [table[u::u16]]\n  7\n  null\n  65535\n]]\n'
	out := lat_roundtrip(src)
	assert out.contains('u::u16'), out
	assert out.contains('65535'), out
	assert out.contains('null'), out
}

fn test_lattice_all_null_declared_column_keeps_type() {
	// I5 audit AF-2 class (b): an all-null n::int column must keep its
	// declared type on the 0x60 lane (pre-W7 it erased to bare n while
	// 0x63 kept n::int — the binary lanes disagreed with each other).
	src := '[m [t [table[n::int]]\n  null\n  null\n]]\n'
	out := lat_roundtrip(src)
	assert out.contains('n::int'), out
}

fn test_lattice_out_of_range_cells_refuse_at_encode() {
	// #807(a), ruled Q4a — audit AF-2: a u::u16 cell 70000 encoded as
	// 4464 (mod 65536) on BOTH binary lanes; probable W3a regression
	// (the pre-W3a encoder widened unsigned→i64 — type drift; W3a's
	// width-keeping flipped the failure axis to silent value wrap).
	// The ruled contract: out-of-range cells REFUSE loudly at encode —
	// never wrap, never silently widen — with the column name and the
	// declared width in the refusal.
	cases := [
		'[m [t [table[u::u16]]\n  70000\n  1\n]]\n',
		'[m [t [table[u::u8]]\n  256\n  1\n]]\n',
		'[m [t [table[u::u32]]\n  4294967296\n  1\n]]\n',
		'[m [t [table[u::u64]]\n  -1\n  1\n]]\n',
		'[m [t [table[i::i8]]\n  200\n  1\n]]\n',
		'[m [t [table[i::i16]]\n  40000\n  1\n]]\n',
		'[m [t [table[i::i32]]\n  3000000000\n  1\n]]\n',
	]
	for src in cases {
		doc := cx.parse(src) or { panic(err) }
		if _ := cx.emit_data_bin(doc) {
			assert false, 'emit_data_bin must refuse the out-of-range cell in:\n${src}'
		} else {
			assert err.msg().contains('out of range'), 'refusal must say out-of-range, got: ${err.msg()}'
		}
	}
}

fn test_lattice_out_of_range_cell_refuses_chunked() {
	// The 0x63 lane refuses identically (the audit verified the wrap
	// on both lanes; the check is the shared cell-range rule).
	src := '[t [table[u::u16]]\n  70000\n  1\n]\n'
	doc := cx.parse(src) or { panic(err) }
	opts := cx.ChunkedEmitOptions{ chunk_size: 2, compress: .never }
	if _ := cx.emit_data_bin_chunked(doc, opts) {
		assert false, 'chunked emit must refuse the out-of-range u16 cell'
	} else {
		assert err.msg().contains('out of range'), 'refusal must say out-of-range, got: ${err.msg()}'
	}
}

fn test_lattice_f16_nonrepresentable_refuses_at_encode() {
	// #807(e), ruled arc-3 (packet §10): a float cell whose value does
	// not round-trip exactly through the declared reduced width REFUSES
	// loudly at encode — never silently approximated (the shortest-
	// round-trip renderer was REJECTED: it masks the approximation
	// behind the original spelling). 1.0e-1 is not binary16-
	// representable; both binary lanes refuse.
	src := '[m [t [table[h::f16]]\n  1.0e-1\n  1.5e0\n]]\n'
	doc := cx.parse(src) or { panic(err) }
	if _ := cx.emit_data_bin(doc) {
		assert false, 'emit_data_bin must refuse the non-representable f16 cell'
	} else {
		assert err.msg().contains('not exactly representable'), 'refusal must name exactness, got: ${err.msg()}'
		assert err.msg().contains('f16'), 'refusal must name the width, got: ${err.msg()}'
	}
	src2 := '[t [table[h::f16]]\n  1.0e-1\n]\n'
	doc2 := cx.parse(src2) or { panic(err) }
	opts := cx.ChunkedEmitOptions{ chunk_size: 2, compress: .never }
	if _ := cx.emit_data_bin_chunked(doc2, opts) {
		assert false, 'chunked emit must refuse the non-representable f16 cell'
	} else {
		assert err.msg().contains('not exactly representable'), 'refusal must name exactness, got: ${err.msg()}'
	}
}

fn test_lattice_f32_nonrepresentable_refuses_at_encode() {
	// The same arc-3 class on the f32 lane (the ruling's wording is
	// width-agnostic): 1.0e-1 is not binary32-representable either.
	src := '[m [t [table[g::f32]]\n  1.0e-1\n]]\n'
	doc := cx.parse(src) or { panic(err) }
	if _ := cx.emit_data_bin(doc) {
		assert false, 'emit_data_bin must refuse the non-representable f32 cell'
	} else {
		assert err.msg().contains('not exactly representable'), 'refusal must name exactness, got: ${err.msg()}'
		assert err.msg().contains('f32'), 'refusal must name the width, got: ${err.msg()}'
	}
}

fn test_lattice_reduced_float_exact_values_roundtrip() {
	// Exactly-representable reduced-width values encode and round-trip
	// render-identically — the refusal is non-representable ONLY.
	// 9.99755859375e-2 IS the f16 value nearest 0.1 (exact dyadic);
	// 2.5e-1 is exact in every width.
	src := '[m [t [table[h::f16 g::f32]]\n  9.99755859375e-2 2.5e-1\n  1.5e0 -2.0e0\n]]\n'
	doc := cx.parse(src) or { panic(err) }
	direct := cx.emit_cx(doc)
	bin := cx.emit_data_bin(doc) or { panic('emit: ${err}') }
	doc2 := cx.parse_data_bin(bin) or { panic('decode: ${err}') }
	assert cx.emit_cx(doc2) == direct, 'exact reduced-width cells must round-trip render-identically'
}

fn test_lattice_declared_alias_names_roundtrip() {
	// #807(c), ruled arc-2 (packet §10): the col-spec's 0x82 declared-
	// name annotation carries the DECLARED spelling when it differs
	// from the code's default render — v::f64 never drifts to
	// v::float, s::string never drops to bare s, n::i64 never drifts
	// to n::int. Both binary lanes; render identity is the assertion.
	src := '[m [t [table[v::f64 s::string n::i64]]\n  1.5e0 x 7\n  2.5e0 y 9\n]]\n'
	doc := cx.parse(src) or { panic(err) }
	direct := cx.emit_cx(doc)
	bin := cx.emit_data_bin(doc) or { panic('emit: ${err}') }
	doc2 := cx.parse_data_bin(bin) or { panic('decode: ${err}') }
	assert cx.emit_cx(doc2) == direct, 'declared alias spellings must survive the 0x60 wire\ndirect:\n${direct}\ngot:\n${cx.emit_cx(doc2)}'
	src_t := '[t [table[v::f64 s::string n::i64]]\n  1.5e0 x 7\n]\n'
	doc_t := cx.parse(src_t) or { panic(err) }
	direct_t := cx.emit_cx(doc_t)
	opts := cx.ChunkedEmitOptions{ chunk_size: 2, compress: .never }
	cbin := cx.emit_data_bin_chunked(doc_t, opts) or { panic('chunked emit: ${err}') }
	doc_c := cx.parse_data_bin(cbin) or { panic('chunked decode: ${err}') }
	assert cx.emit_cx(doc_c) == direct_t, 'declared alias spellings must survive the 0x63 wire'
}

fn test_lattice_annotation_minimality() {
	// The annotation is emitted IFF the declared spelling differs from
	// the code's default render (canonical determinism — redundant
	// annotations never ride): a v::float col-spec is byte-identical
	// to its pre-annotation form; the same table spelled v::f64 is
	// exactly 6 bytes longer (0x82 + 0x30 + uvarint(3) + 'f64').
	base := cx.parse('[t [table[v::float]]\n  1.5e0\n]\n') or { panic(err) }
	alias := cx.parse('[t [table[v::f64]]\n  1.5e0\n]\n') or { panic(err) }
	base_bin := cx.emit_data_bin(base) or { panic(err) }
	alias_bin := cx.emit_data_bin(alias) or { panic(err) }
	assert alias_bin.len == base_bin.len + 6, 'annotation must cost exactly its own bytes (got ${alias_bin.len} vs ${base_bin.len})'
}

fn test_lattice_mixed_declared_kind_roundtrip() {
	// #807 (the 0x81 declared-kind drop, ttp-013's class): a DECLARED
	// column that falls to the 0x81 mixed escape keeps its declared
	// name through the annotation — m::int never decodes bare.
	src := '[m [t [table[m::int]]\n  1\n  [\'a\', \'b\']\n  3\n]]\n'
	doc := cx.parse(src) or { panic(err) }
	direct := cx.emit_cx(doc)
	bin := cx.emit_data_bin(doc) or { panic('emit: ${err}') }
	doc2 := cx.parse_data_bin(bin) or { panic('decode: ${err}') }
	assert cx.emit_cx(doc2) == direct, 'the 0x81 escape must keep the declared kind\ndirect:\n${direct}\ngot:\n${cx.emit_cx(doc2)}'
	assert cx.emit_cx(doc2).contains('m::int'), cx.emit_cx(doc2)
}

fn test_lattice_nullable_declared_alias_roundtrip() {
	// Annotation composes with the 0x80 wrapper: the declared spelling
	// wins over the inner-code refinement (n::i64 with nulls stays
	// n::i64, never the inner's default 'int').
	src := '[m [t [table[n::i64]]\n  7\n  null\n]]\n'
	out := lat_roundtrip(src)
	assert out.contains('n::i64'), out
}

fn test_lattice_datetime_offset_rides_transport() {
	// #807(d), ruled arc-2 (packet §10): the §3.6.1 wire form ALREADY
	// carries offset_minutes; the transport encoders carry the parsed
	// offset (unix_nanos stays UTC-normalized) so the local render
	// survives both binary lanes. The Tier-1 hash agreed all along
	// (strict canonical normalizes) — this is render parity.
	src := "[m [t [table[w::datetime]]\n  '2026-01-01T23:00:00+02:00'\n  '2026-01-02T00:00:00Z'\n]]\n"
	doc := cx.parse(src) or { panic(err) }
	direct := cx.emit_cx(doc)
	bin := cx.emit_data_bin(doc) or { panic('emit: ${err}') }
	doc2 := cx.parse_data_bin(bin) or { panic('decode: ${err}') }
	assert cx.emit_cx(doc2) == direct, 'datetime offsets must survive the 0x60 wire\ndirect:\n${direct}\ngot:\n${cx.emit_cx(doc2)}'
	assert cx.emit_cx(doc2).contains('+02:00'), cx.emit_cx(doc2)
	src_t := "[t [table[w::datetime]]\n  '2026-01-01T23:00:00+02:00'\n]\n"
	doc_t := cx.parse(src_t) or { panic(err) }
	direct_t := cx.emit_cx(doc_t)
	opts := cx.ChunkedEmitOptions{ chunk_size: 2, compress: .never }
	cbin := cx.emit_data_bin_chunked(doc_t, opts) or { panic('chunked emit: ${err}') }
	doc_c := cx.parse_data_bin(cbin) or { panic('chunked decode: ${err}') }
	assert cx.emit_cx(doc_c) == direct_t, 'datetime offsets must survive the 0x63 wire'
}

fn test_lattice_decoded_datetime_offset_survives_reencode() {
	// The scalar 0x32 form is decode-side-produced (DataDateTime) —
	// text-parsed scalars ride as strings. The live witness for the
	// scalar encoder's offset carry is decode→re-encode fidelity: an
	// offset-bearing wire datetime survives a second encode byte-true.
	src := "[t [table[w::datetime]]\n  '2026-01-01T23:00:00+02:00'\n]\n"
	doc := cx.parse(src) or { panic(err) }
	bin := cx.emit_data_bin(doc) or { panic('emit: ${err}') }
	doc2 := cx.parse_data_bin(bin) or { panic('decode: ${err}') }
	bin2 := cx.emit_data_bin(doc2) or { panic('re-encode: ${err}') }
	assert bin2 == bin, 'decode→re-encode must be byte-stable with the offset riding'
}

fn test_lattice_width_boundary_cells_roundtrip() {
	// Exactly-at-boundary values encode and round-trip intact on the
	// plain lane — the refusal is out-of-range ONLY.
	src := '[m [t [table[a::u16 b::u8 c::i8 d::i16 e::u64]]\n  65535 255 -128 -32768 9223372036854775807\n  0 0 127 32767 0\n]]\n'
	out := lat_roundtrip(src)
	assert out.contains('65535'), out
	assert out.contains('-32768'), out
	assert out.contains('9223372036854775807'), out
	assert out.contains('a::u16'), out
}

fn test_lattice_string_dictionary_by_savings() {
	// A highly repetitive string column dict-encodes (the §3.10.2
	// canonical byte-savings rule); a distinct-per-row column stays
	// plain. Both round-trip identically either way.
	src := '[m [t [table[region::string]]\n  west-coast-region-1\n  west-coast-region-1\n  west-coast-region-1\n  west-coast-region-1\n]]\n'
	out := lat_roundtrip(src)
	assert out.contains('west-coast-region-1'), out
}

fn test_lattice_chunked_nullable_roundtrip() {
	// §3.10.5 in the chunked header (stream 17 W3c): a null-bearing
	// column wraps 0x80 in the col-spec; every row group emits the
	// wrapper scoped to its rows; null positions round-trip exactly
	// across group boundaries.
	mut rows_src := []string{}
	for i in 0 .. 10 {
		if i % 3 == 1 {
			rows_src << '  null'
		} else {
			rows_src << '  ${i}'
		}
	}
	src := '[t [table[n::int]]\n' + rows_src.join('\n') + '\n]\n'
	doc := cx.parse(src) or { panic(err) }
	direct := cx.emit_cx(doc)
	bin := cx.emit_data_bin_chunked(doc, chunk_size: 4) or { panic('chunked emit: ${err}') }
	doc2 := cx.parse_data_bin(bin) or { panic('decode: ${err}') }
	out := cx.emit_cx(doc2)
	assert out == direct, 'chunked nullable round-trip:\ndirect:\n${direct}\ngot:\n${out}'
}

fn test_lattice_projected_column_read() {
	// parse_data_bin_projected (stream 17 W4, #710 item 2): only the
	// wanted columns MATERIALIZE — every other column's payload
	// cursor-skips (bool bitpack, f16, decimal, the atom dictionary,
	// strings, 0x80 nullable), coming back as null placeholders.
	// Cursor exactness is witnessed by the LAST column decoding
	// correctly after skipping every representation in between.
	src := '[t [table[u::u16 flag::bool h::f16 p::decimal status::atom note::string maybe::int val::int]]\n' +
		'  1 false 1.5e0 19.99 :alpha zebra-note-a null 7\n' +
		'  2 true -2.0e0 8.50 :beta zebra-note-b 5 9\n]\n'
	doc := cx.parse(src) or { panic(err) }
	bin := cx.emit_data_bin(doc) or { panic('emit: ${err}') }
	pdoc := cx.parse_data_bin_projected(bin, ['u', 'val']) or { panic('projected decode: ${err}') }
	out := cx.emit_cx(pdoc)
	assert out.contains('7'), out
	assert out.contains('9'), out
	assert !out.contains('19.99'), out
	assert !out.contains('zebra-note-a'), out
	assert !out.contains('alpha'), out
	assert out.contains('null'), out
	// The same bytes still decode in FULL — the projection is a read
	// posture, never a different wire.
	full := cx.parse_data_bin(bin) or { panic('full decode: ${err}') }
	fout := cx.emit_cx(full)
	assert fout.contains('19.99'), fout
	assert fout.contains('zebra-note-b'), fout
}
